import { parseOpeningHours } from "./openingHours";

const closedWeek = () => ({ Mo: [], Tu: [], We: [], Th: [], Fr: [], Sa: [], Su: [] });

test("a single day with a single range", () => {
  expect(parseOpeningHours("Mo 08:00-12:00")).toEqual({
    ...closedWeek(),
    Mo: [{ from: "08:00", to: "12:00" }],
  });
});
