bun test 2>&1 | tail -5

python3 - <<'PY'
p='src/openingHours.ts'
s=open(p).read()
start=s.index('class Parser {')
s=s[:start]+'''class Parser {
  private position = 0;

  constructor(
    private readonly tokens: Token[],
    private readonly endColumn: number,
  ) {}

  parse(): WeeklyHours {
    const hours = Object.fromEntries(DAYS.map((day) => [day, []])) as unknown as WeeklyHours;
    do {
      this.parseRule(hours);
    } while (this.accept(";"));
    if (this.peek()) throw this.unexpected();
    return hours;
  }

  private parseRule(hours: WeeklyHours): void {
    const days: Day[] = [];
    do {
      days.push(...this.parseDayItem());
    } while (this.accept(","));

    const ranges: TimeRange[] = [];
    const token = this.peek();
    if (token?.kind === "word" && token.text === "off") {
      this.next();
    } else if (token?.kind === "time") {
      do {
        ranges.push(this.parseRange());
      } while (this.accept(","));
      ranges.sort((a, b) => a.from.localeCompare(b.from));
    } else {
      throw this.unexpected();
    }
    for (const day of days) hours[day] = ranges.map((range) => ({ ...range }));
  }

  private parseRange(): TimeRange {
    const from = this.expect("time").text;
    this.expect("-");
    const to = this.expect("time").text;
    return { from, to };
  }

  private parseDayItem(): Day[] {
    const first = this.parseDay();
    const last = this.accept("-") ? this.parseDay() : first;
    const days: Day[] = [DAYS[first]];
    for (let i = first; i !== last; ) {
      i = (i + 1) % DAYS.length;
      days.push(DAYS[i]);
    }
    return days;
  }

  private parseDay(): number {
    const token = this.expect("word");
    const index = DAYS.indexOf(token.text as Day);
    if (index === -1) throw new OpeningHoursError("UNKNOWN_DAY", token.column, `Unknown day "${token.text}"`);
    return index;
  }

  private peek(): Token | undefined {
    return this.tokens[this.position];
  }

  private next(): Token {
    return this.tokens[this.position++];
  }

  private accept(kind: TokenKind): boolean {
    if (this.peek()?.kind !== kind) return false;
    this.position++;
    return true;
  }

  private expect(kind: TokenKind): Token {
    if (this.peek()?.kind !== kind) throw this.unexpected();
    return this.next();
  }

  private unexpected(): OpeningHoursError {
    const token = this.peek();
    if (!token) return new OpeningHoursError("UNEXPECTED", this.endColumn, "Unexpected end of text");
    return new OpeningHoursError("UNEXPECTED", token.column, `Unexpected "${token.text}"`);
  }
}

export function parseOpeningHours(text: string): WeeklyHours {
  if (/^ *$/.test(text)) throw new OpeningHoursError("EMPTY", 1, "No opening hours given");
  return new Parser(tokenize(text), text.length + 1).parse();
}
'''
open(p,'w').write(s)
PY
timeout 20 bun test 2>&1 | grep -E "\(fail\)|pass$|fail$" | tail -30
